int sum = 0;
for (int i = 1; i <= 30; i++)
    if (i % 5 == 4)
        sum += i;
cout << sum;

void foo(int arr[], int size) {
    for (int i = 0; i < size; ++i) arr[i] += i;
}
int bar(int n) {
    if (n <= 1) return 1;
    return n * bar(n - 2);
}
int main() {
    int arr[5] = {1,2,3,4,5};
    foo(arr, 5);
    int result = 0;
    for (int i = 0; i < 5; ++i)
        result += bar(arr[i]);
    cout << "Result=" << result;
    return 0;
}
